39	public abstract class BaseTask extends FortressExecutable {
40	    // Could get this by hacking ForkJoinTask's status field, but
41	    // not touching that for now as it's too changeable
42	    private static final int UNFORKED = 0;
43	    private static final int FORKED = 1;
