51	    private static Boolean debug = false;
52	
53	    private static void debug(String s) {
54	        if (debug)
55	            System.out.println("BaseTaskDebug: " + Thread.currentThread().getName() + ":" + s);
56	    }
57	
58	    /** Each base task has a depth in the pedigree tree, the value of
59	    the next magic number, a unique gamma value that is the dot
60	    product of the task's pedigree and the magic numbers array, and a
61	    dot product that is the task's gamma value with extra magic added
62	    in for each random number the task generates **/
63	
64	    private int depth;
65	    private long nextMagicNumber; 
66	    private long gamma; 
67	    private long dotProduct;
68	    
69	    // The constructor used by the primordial task.
70	    public BaseTask() {
71	        super();
72	        this.parent = null;
73	        this.transaction = null;
74	
75	        // Pedigree information
76	        this.depth = 0;
77	        this.nextMagicNumber = 
78	            MagicNumbers.trulyRandomLongNumbers(this.depth + 1);
79	        this.gamma = 
80	            MagicNumbers.trulyRandomLongNumbers(this.depth);
81	        this.dotProduct = this.gamma;
82	    }
83	
