85	        super();
86	        this.parent = parent;
87	        this.transaction = parent.transaction;
88	
89	        // Pedigree information
90	        this.depth = parent.getDepth() + 1;
91	        this.nextMagicNumber = 
92	            MagicNumbers.trulyRandomLongNumbers(this.depth + 1);
93	        this.gamma = parent.makeNewChild();
94	        this.dotProduct = this.gamma;
95	    }
96	
97	    private int getDepth() {
98	        return this.depth;
99	    }
100	
101	    /* Returns a unique gamma for a child task */
102	    public long makeNewChild() {
103	        this.gamma += this.nextMagicNumber;
104	        return this.gamma;
105	    }
106	
107	    /* Records that a new random number has been asked for, and
108	     * returns the task's dotProduct */
109	    public long makeNewRandom() {
110	        this.dotProduct += this.nextMagicNumber;
111	        return dotProduct;
112	    }
