148	        // Emphasize common UNFORKED case.
149	        if (actuallyForked == UNFORKED) {
150	            this.compute();
151	        } else if (useHelpJoin) {
152	            this.helpJoin();
153	        } else {
154	            this.join();
155	        }
156	    }
