169	        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
170	        BaseTask currentTask = ftr.getTask();
171	        debug("endTransaction: ftr = " + ftr + " current task = " + currentTask);
172	        Transaction transaction = ftr.getTask().transaction();
173	        debug("End transaction ftr = " + ftr + " current action = " + currentTask + " trans = " + transaction);
174	        if (transaction != null) {
175	            transaction.TXCommit();
176	            currentTask.setTransaction(transaction.getParent());
177	        }
178	        ftr.recordEndTransaction();
179	    }
