182	        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
183	        BaseTask currentTask = ftr.getTask();
184	        Transaction transaction = ftr.getTask().transaction();
185	        debug("Cleanup transaction ftr = " + ftr + " current action = " + currentTask + " trans = " + transaction);
186	        if (transaction != null)
