199	            long waitNanoseconds = (long) ((1L << (ftr.getRetries() + machineConstant)) * r);
200	            
201	            while (elapsedTime < waitNanoseconds) {
202	                elapsedTime = System.nanoTime() - startTime;
203	            }
204	        }
205	        
206	        ftr.incElapsedTime(elapsedTime);
207	        ftr.incRetries();
