26	
27	    public TupleTask(Expr ex, Evaluator ev) {
28	        super(FortressTaskRunner.getTask());
29	        expr = ex;
30	        eval = ev;
31	    }
32	
33	    public void compute() {
34	        FortressTaskRunner.setCurrentTask(this);
35	        try {
36	            Environment inner = eval.e.extendAt(expr);
37	            Evaluator e = new Evaluator(inner);
38	            res = expr.accept(e);
39	        }
40	        catch (NullPointerException e) {
