100	        desc = Naming.mangleMethodSignature(desc, erasedContent, true);
101	        boolean is_not_special = ! Naming.pointyDelimitedInitMethod(_name);
102	        _name = Naming.mangleMemberName(ManglingClassWriter.TWEAK_ERASED_UNIONS && is_not_special ? _name + erasedContent: _name);  // Need to mangle somehow if NOT ERASED
103	     
104	        super.visitMethodInsn(opcode, owner, _name, desc);
105	    }
