11	package com.sun.fortress.compiler.codegen;
12	
13	import com.sun.fortress.compiler.nativeInterface.SignatureParser;
14	
15	// This class allows us to wrap MethodVisitor.visitMaxs Methods to
16	// dump bytecodes.  It is generally used with CodeGenClassWriter.
17	
18	import java.util.*;
19	
20	import org.objectweb.asm.*;
21	import org.objectweb.asm.util.*;
22	
23	import com.sun.fortress.runtimeSystem.Naming;
24	import com.sun.fortress.useful.Debug;
25	import com.sun.fortress.compiler.NamingCzar;
26	import com.sun.fortress.exceptions.CompilerError;
27	
28	public class CodeGenMethodVisitor extends TraceMethodVisitor {
29	    // All these fields are passed to the constructor, but never
30	    // used except possibly for debugging after the constructor has run.
31	    private int access;
32	    private String name;
33	    private String desc;
34	    private String signature;
35	    private String[] exceptions;
36	    private List<String> argumentTypes;
37	    private String resultType;
38	
39	    // Only these fields are actually required to generate code.
40	    int localVariableCount;
41	    boolean hasThis;
42	
43	    // This stuff is kept around to emit debugging information.
44	    // All these lists are managed stack-fashion and indexed by handle.
45	    private List<String> varNames;
46	    private List<String> varTypes;
47	    private List<Label> varFirstUse;
48	
49	    public CodeGenMethodVisitor(int access, String name, String desc,
50	                                String signature, String[] exceptions,
51	                                MethodVisitor mvisitor) {
52	        super(mvisitor);
53	        this.access = access;
54	        this.name = name;
55	        this.desc = desc;
56	        this.signature = signature;
57	        this.exceptions = exceptions;
58	        this.argumentTypes = NamingCzar.parseArgs(desc);
59	        this.resultType = NamingCzar.parseResult(desc);
60	        this.localVariableCount = 0;
61	
62	        int sz = 5 + this.localVariableCount + this.argumentTypes.size();
63	        this.varNames = new ArrayList(sz);
64	        this.varTypes = new ArrayList(sz);
65	        this.varFirstUse = new ArrayList(sz);
66	
67	        this.hasThis = (access & Opcodes.ACC_STATIC) != Opcodes.ACC_STATIC;
68	
69	        Debug.debug(Debug.Type.CODEGEN, 2,
70	                    "MethodVisitor: name = " , name , " desc = " , desc ,
71	                    " argumentTypes = " , argumentTypes , " resultType " , resultType);
72	
73	    }
74	
75	    public void dump() {
76	        Debug.debug(Debug.Type.CODEGEN, 2,
77	                    "MethodVisitor: name = " , name , " desc = " , desc ,
78	                    " access = " , access , " signature = " , signature ,
79	                    " exceptions " , exceptions ,
80	                    " argumentTypes = " , argumentTypes , " resultType " , resultType);
81	    }
82	
83	    public void visitMaxs(int maxStack, int maxLocals) {
84	        dumpBytecodes();
85	        super.visitMaxs(maxStack, maxLocals);
86	    }
87	
88	    public void dumpBytecodes() {
89	        Debug.debug(Debug.Type.CODEGEN, 2, getText());
90	    }
91	
92	    private String getStackTrace() {
93	        String result = "\n";
94	        StackTraceElement[] ste = Thread.currentThread().getStackTrace();
95	
96	        for (StackTraceElement s : ste) result = result + s + "\n";
97	        return result;
98	    }
99	
100	    private String opc(int opcode) {
101	        return com.sun.fortress.compiler.asmbytecodeoptimizer.Opcodes.opcNames[opcode];
102	    }
103	
104	    public void visitFieldInsn(int opcode, String owner, String name, String desc) 
105	    {
106	        Debug.debug(Debug.Type.CODEGEN, 2, "visitFieldInsn: ", opc(opcode), " owner = " + owner, " name = ", name, " desc = ", desc, getStackTrace());
107	        super.visitFieldInsn(opcode, owner,name,desc);
108	    }
109	
110	    public void visitIincInsn(int var, int increment) {
111	        Debug.debug(Debug.Type.CODEGEN, 2, "visitIincInsn: var = ", var , " increment = ", increment, getStackTrace());
112	        super.visitIincInsn(var, increment);
113	    }
114	
115	    public void visitInsn(int opcode) {
116	        Debug.debug(Debug.Type.CODEGEN, 2, "visitInsn:", opc(opcode), getStackTrace());
117	        super.visitInsn(opcode);
118	    }
119	    
120	    public void visitIntInsn(int opcode, int operand) {
121	        Debug.debug(Debug.Type.CODEGEN, 2, "visitIntInsn:", opc(opcode), " ", operand, " " , getStackTrace());
122	        super.visitIntInsn(opcode, operand);
123	    }
124	
125	    public void visitJumpInsn(int opcode, Label label) {
126	        Debug.debug(Debug.Type.CODEGEN, 2, "visitJumpInsn:", opc(opcode), " ", label, " " , getStackTrace());
127	        super.visitJumpInsn(opcode, label);
128	    }
129	
130	    public void visitLabel(Label label) {
131	        Debug.debug(Debug.Type.CODEGEN, 2, "visitLabel:", label);
132	        super.visitLabel(label);
133	    }
134	
135	    public void visitLdcInsn(Object cst) {
136	        Debug.debug(Debug.Type.CODEGEN, 2, "visitLdcInsn:", cst);
137	        super.visitLdcInsn(cst);
138	    }
139	
140	    public void visitMethodInsn(int opcode, String owner, String name, String desc) {
141	        Debug.debug(Debug.Type.CODEGEN, 2, "visitMethodInsn:", opc(opcode), " owner = ", owner, " name = ", name, " desc = ", desc, getStackTrace());
142	        super.visitMethodInsn(opcode, owner, name, desc);
143	    }
144	
145	    public void visitTypeInsn(int opcode, String type) {
146	        Debug.debug(Debug.Type.CODEGEN, 2, "visitTypeInsn:", opc(opcode), " type = ",  type, getStackTrace());
147	        super.visitTypeInsn(opcode, type);
148	    }
149	
150	    public void visitVarInsn(int opcode, int var) {
151	        Debug.debug(Debug.Type.CODEGEN, 2, "visitVarInsn:", opc(opcode), " var = " , var, getStackTrace());
152	        super.visitVarInsn(opcode, var);
153	    }
154	
155	    /**
156	     * the correct way to get a local is to call createCompilerLocal,
157	     * which will give you a stack offset that acts as a handle on the
158	     * local variable you requested, and then to hand that local
159	     * variable back again when you're done by calling
160	     * disposeCompilerLocal so that debug information can be generated
161	     * where possible, and so that stack slots can be reused in a
162	     * sensible way.  If you are representing a variable in Fortress
163	     * source code, you should do this in the constructor for a
164	     * VarCodeGen; CodeGen maintains a lexEnv that maps a Fortress
165	     * variable to the corresponding VarCodeGen. */
166	
167	    // Non-user-accessible local variable
168	    public int createCompilerLocal(String _name, String type) {
169	        if (localVariableCount != varNames.size()) {
170	            throw new CompilerError("Trying to create local " + _name +
171	                                       " but current metadata is off\nlocalVariableCount = " +
172	                                       localVariableCount +
173	                                       "\nvarNames = " + varNames);
174	        }
175	        Debug.debug(Debug.Type.CODEGEN, 2,
176	                    "LOCAL create ", localVariableCount, " ", _name);
177	        varNames.add(_name);
178	        varTypes.add(type);
179	        Label start = new Label();
180	        visitLabel(start);
181	        varFirstUse.add(start);
182	
183	        return localVariableCount++;
184	    }
185	
186	    // I need to reserve slot 0.  
187	    public int reserveSlot0() {
188	        return createCompilerLocal("this", null);
189	    }
190	
191	    public void disposeCompilerLocal(int localId) {
192	        if (localId >= localVariableCount) {
193	            throw new CompilerError("Trying to dispose of local " + localId +
194	                                       " but current metadata is off\nlocalVariableCount = " +
195	                                       localVariableCount +
196	                                       "\nvarNames = " + varNames);
197	        }
198	        String ty = varTypes.get(localId);
199	        if (ty != null) {
200	            Label finish = new Label();
201	            visitLabel(finish);
202	            visitLocalVariable(varNames.get(localId), ty, null, varFirstUse.get(localId), finish, localId);
203	        }
204	        Debug.debug(Debug.Type.CODEGEN, 2,
205	                    "LOCAL destroy ", localId, " ", varNames.get(localId));
206	        if (localId == (localVariableCount-1)) {
207	            varNames.remove(localId);
208	            varTypes.remove(localId);
209	            varFirstUse.remove(localId);
210	            localVariableCount--;
211	        } else {
212	            varNames.set(localId, null);
213	            varTypes.set(localId, null);
214	            varFirstUse.set(localId, null);
215	        }
216	    }
217	
218	    public int getThis() {
219	        if (hasThis) {
220	            return 0;
221	        } else {
222	            throw new CompilerError("Trying to get this/self in static method.");
223	        }
224	    }
225	
226	}
