126	        conversionTable = new HashMap();
127		// If you change these, you may also need to change items in file NamingCzar.java
128	        initializeEntry("FZZ32",    "getValue", "()I", "make", "(I)L" + prefix + "FZZ32;");
129	        initializeEntry("FZZ64",    "getValue", "()J", "make", "(J)L" + prefix + "FZZ64;");
130	        initializeEntry("FNN32",    "getValue", "()I", "make", "(I)L" + prefix + "FNN32;");
131	        initializeEntry("FNN64",    "getValue", "()J", "make", "(J)L" + prefix + "FNN64;");
132	        initializeEntry("FRR32",    "getValue", "()F", "make", "(F)L" + prefix + "FRR32;");
133	        initializeEntry("FRR64",    "getValue", "()D", "make", "(D)L" + prefix + "FRR64;");
134	        initializeEntry("FBoolean", "getValue", "()Z", "make", "(Z)L" + prefix + "FBoolean;");
135	        initializeEntry("FVoid",    "getValue", "()",  "make", "()L" + prefix + "FVoid;");
136	        initializeEntry("FJavaString",  "getValue", "()Ljava/lang/String;",
137	                                    "make", "(Ljava/lang/String;)L" + prefix + "FJavaString;");
138	        initializeEntry("FCharacter",    "getValue",	"()I", "make", "(I)L" + prefix + "FCharacter;");
139	        initializeEntry("FJavaBufferedReader", "getValue", "()Lcom/sun/fortress/compiler/runtimeValues/FortressBufferedReader;",
140	                                    "make", "(Lcom/sun/fortress/compiler/runtimeValues/FortressBufferedReader;)L" + prefix + "FJavaBufferedReader;");
141	        initializeEntry("FJavaBufferedWriter", "getValue", "()Lcom/sun/fortress/compiler/runtimeValues/FortressBufferedWriter;",
142	                                    "make", "(Lcom/sun/fortress/compiler/runtimeValues/FortressBufferedWriter;)L" + prefix + "FJavaBufferedWriter;");
143	        initializeEntry("FZZ", "getValue", "()Ljava/math/BigInteger;",
144	                "make", "(Ljava/math/BigInteger;)L" + prefix + "FZZ;");
145	        initializeEntry("FVector", "getValue", "()[I" , "make","([I)L"+ prefix + "FVector;");
146	    }
