148	    // Strip off the leading L + prefix, and trailing ;"
149	
150	    static String strip(String s) {
151	        // String header = "L" + prefix;
152	        String trailer = ";";
153	        int end = s.lastIndexOf(";");
154	        int start = s.lastIndexOf("/") + 1; // header.length();
155	        return s.substring(start,end);
156	    }
