158	    static String descToType(String s) {
159	        if (! (s.startsWith("L") && s.endsWith(";")))
160	            throw new IllegalArgumentException("Input string " + s + " must begin with 'L' and end with ';'");
161	        
162	        return Useful.substring(s,1,-1);
163	    }
