165	    public FortressMethodAdapter(CodeGenClassWriter cv,
166	            String inputClassName,
167	            String outputClassName,
168	            APIName api_name,
169	            Map<IdOrOpOrAnonymousName,MultiMap<Integer, Functional>> size_partitioned_overloads,
170	            TypeAnalyzer ta) {
171	        super(cv);
172	        this.cw = cv;
173	        this.inputClassName = inputClassName.replace('.','/');
174	        this.outputClassName = outputClassName.replace('.','/');
