182	            String superName, String[] interfaces) {
183	        Debug.debug(Debug.Type.COMPILER, 1, "visit:" + name + " generate "
184	                + inputClassName);
185	        cv.visit(version, access, outputClassName, signature, superName,
186	                interfaces);
187	
188	        /*
189	         * TODO there may be more work be done in the method called below.
190	         * cg=null allows a bunch of code reuse, but does not deal with the
191	         * possibility of unambiguous reference to one of these
192	         * adapter-generated overloaded (?) native methods.
193	         */
194	
195	        overloadedNamesAndSigs = CodeGen.generateTopLevelOverloads(apiName,
196	                sizePartitionedOverloads, ta, cw, /* cg= */null,
