205	            String signature, String[] exceptions) {
206	        // Don't know how to do these, or if we need them...
207	        if (name.equals("<init>") || name.equals("<clinit>"))
208	            Debug.debug(Debug.Type.COMPILER, 1, "Don't visit Method ", name);
209	        else if (SignatureParser.unsayable(desc))
210	            Debug.debug(Debug.Type.COMPILER, 1,
211	                    "Don't visit Method with unsayable desc", name);
212	        else {
213	
214	            generateNewBody(access, desc, signature, exceptions, name, name);
215	
216	        }
217	
218	        return new EmptyVisitor();// super.visitMethod(access, name, desc, signature, exceptions);
219	    }
