221	    static class SignatureAndConverter {
222	        final fortressConverter converter;
223	        final String signature;
224	        SignatureAndConverter(String signature, fortressConverter converter) {
225	            this.converter = converter;
226	            this.signature = signature;
227	        }
228	    }
229	    
230	    /**
231	     * converts an input, foreign, Java type descriptor into the Java type
232	     * descriptor for the implementation of the corresponding Fortress type.
233	     * 
234	     * The name is an abbreviation for toImplForFortressForForeign.
235	     * 
236	     * @param arg_desc
237	     * @return
238	     */
239	    private SignatureAndConverter toImplFFFF(String jvmArgType, String method_name, boolean isResultType) {
240	        com.sun.fortress.nodes.Type ftype = NamingCzar.fortressTypeForForeignJavaType(jvmArgType, method_name, isResultType);
241	        if (ftype == null) {
242	            // Perhaps this type is in the Fortress implementation hierarchy.
243	            if (NamingCzar.jvmTypeExtendsAny(jvmArgType))
244	                return new SignatureAndConverter(jvmArgType, emptyConverter.ONLY);;
245	            
246	            throw new Error("No Fortress type (yet) for foreign Java type descriptor '" + jvmArgType + "'");
247	        }
248	        String fortressArgType = NamingCzar.jvmTypeDesc(ftype, null);
249	        if (fortressArgType == null)
250	            throw new Error("No Java impl type (yet) for Fortress type " + ftype + " for foreign descriptor '" + jvmArgType + "'");
251	        String stripped = strip(fortressArgType);
252	        fortressConverter converter = (fortressConverter) conversionTable
253	                .get(stripped);
254	        
255	        if (converter == null)
256	            throw new RuntimeException("Can't generate header for method "
257	                    + method_name + " with jvm desc =" + jvmArgType + " stripped = " + stripped);
258	        
259	        return new SignatureAndConverter(fortressArgType, converter);
260	    }
261	    
262	    private MethodVisitor generateNewBody(int access, String desc, String signature,
263	            String[] exceptions, String name, String newName) {
264	
265	        Debug.debug(Debug.Type.COMPILER, 1, "generateNewBody: ", name,
266	                    " with desc ", desc);
267	
268	        SignatureParser sp = new SignatureParser(desc);
269	        
270	        List<String> desc_args = sp.getJVMArguments();
271	        String desc_result = sp.getJVMResult();
272	        List<String> fortress_args = new ArrayList<String>();
273	        List<fortressConverter> convert_args = new ArrayList<fortressConverter>();
274	
275	        String fsig = "(";
276	        StringBuilder buf = new StringBuilder();
277	        buf.append(fsig);
278	        for (String s : desc_args) {
279	             
280	            SignatureAndConverter s_a_c = toImplFFFF(s, name, false);
281	            buf.append(s_a_c.signature);
282	            fortress_args.add(s_a_c.signature);
283	            
284	            convert_args.add(s_a_c.converter);
285	        }
286	        fsig = buf.toString();
287	        SignatureAndConverter s_a_c = toImplFFFF(desc_result, name, true);
288	        fsig = fsig + ")" + s_a_c.signature;
289	        
290	        fortressConverter convert_result = s_a_c.converter;
291	    
292	        // FORWARDING METHOD, only with type conversions on the way in/out!
293	        MethodVisitor mv = cv.visitMethod(access, name, fsig, signature,
294	                exceptions);
295	        mv.visitCode();
296	        Label l0 = new Label();
297	        mv.visitLabel(l0);
298	        int count = 0;
299	        for (String s : fortress_args) {
300	            fortressConverter converter = convert_args.get(count);
301	            mv.visitVarInsn(Opcodes.ALOAD, count++);
302	            converter.convertArg(mv, s);
303	        }
304	
305	        Debug.debug(Debug.Type.COMPILER, 1, "className = ", inputClassName,
306	                    " name = ", name, " access = ", access);
307	
308	        mv.visitMethodInsn(Opcodes.INVOKESTATIC, inputClassName, name, sp
309	                .getSignature());
310	        
311	        convert_result.convertResult(mv, s_a_c.signature);
312	
313	        mv.visitInsn(Opcodes.ARETURN);
314	        mv.visitMaxs(2, 1);
315	        mv.visitEnd();
316	        return mv;
317	    }
318	
319	    public void visitEnd() {
320	
321	        super.visitEnd();
322	    }
